15	  // Subtotal: 95000, VAT: 19950, Total: 114950
16	  assert.equal(
17	    text,
18	    `DRAFT
19	Blue Fern Bakery
20	10 x Development (hour) @ €95.00 = €950.00
21	VAT: €199.50
22	Total: €1,149.50`
23	  );
24	});
