  // Subtotal: 1080000, VAT: 226800, Total: 1306800
  assert.equal(
    text,
    `DRAFT
Blue Fern Bakery
9 x Logo package @ €1,200.00 = €10,800.00
VAT: €2,268.00
Total: €13,068.00
Due: 2024-11-14`
  );
});

test('renderInvoiceText: different customers', () => {
